using System;using System.IO;using System.Reflection;using System.Collections.Generic;using System.Security.Cryptography;
class Tests{
[STAThread]static int Main(string[] args){var assembly=Assembly.LoadFile(Path.GetFullPath(args[0]));var type=assembly.GetType("StudentTong.Setup.EnvironmentApp");int passed=0;foreach(string test in new[]{"valid","traversal","link","checksum"}){string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"case-"+test);Directory.CreateDirectory(Path.Combine(root,"downloads"));string archive=Path.Combine(root,"downloads","playwright-core.tgz");File.Copy(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,test+".tgz"),archive,true);string hash;using(var s=SHA256.Create())hash=BitConverter.ToString(s.ComputeHash(File.ReadAllBytes(archive))).Replace("-","").ToLowerInvariant();var manifest=new Dictionary<string,object>{{"playwrightCore",new Dictionary<string,object>{{"url","https://example.invalid/offline-fixture"},{"sha256",hash},{"version","1.62.1"}}}};object form=Activator.CreateInstance(type,BindingFlags.Instance|BindingFlags.NonPublic,null,new object[]{new string[0]},null);type.GetField("root",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(form,root);type.GetField("manifest",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(form,manifest);bool rejected=false;try{type.GetMethod("Core",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(form,null);}catch(TargetInvocationException ex){rejected=true;Console.WriteLine(test+" rejected: "+ex.InnerException.Message);}if((test=="valid"&&rejected)||(test!="valid"&&!rejected))throw new Exception("Parser invariant failed: "+test);if(File.Exists(Path.Combine(root,"temp","escape.txt")))throw new Exception("Path escaped");((IDisposable)form).Dispose();passed++;}Console.WriteLine("NATIVE_ARCHIVE_CONTRACTS_PASSED "+passed);return 0;}}
